import json, pathlib
root=pathlib.Path(__file__).parent
sources={
 'google':'https://developers.google.com/machine-learning/crash-course/neural-networks/nodes-hidden-layers',
 'stanford':'https://cs231n.github.io/optimization-2/',
 'sanderson':'https://www.3blue1brown.com/lessons/backpropagation/',
 'pytorch':'https://docs.pytorch.org/tutorials/beginner/basics/autogradqs_tutorial.html'}
def ev(s,locator,claim):return {'url':sources[s],'locator':locator,'claim':claim,'access':'supplied verified source packet'}
nodes=[]
def node(id,q,a,status='supported',evidence=None):nodes.append(dict(id=id,question=q,answer=a,status=status,evidence=evidence or []))
node('arithmetic','What can the reader already calculate?','Addition, subtraction, multiplication, squaring, comparisons, and arithmetic expressions evaluated with Python variables and functions.','assumed')
node('parameters','What does a tiny network calculate, and which numbers can learning change?','Inputs describe an example. A weight multiplies an input; a bias adds a shift. These adjustable numbers determine intermediate hidden values and predictions. A forward pass evaluates the operations using the current parameters.',evidence=[ev('google','Opening linear-model equation; Adding layers to the network','Weighted input sums plus biases produce intermediate and output values; parameters are adjustable.')])
node('activation','Why put a nonlinear operation between weighted sums, and what does ReLU calculate?','Several weighted sums alone collapse to a single linear calculation. We need an explicit simple activation rule for the arithmetic example: propose ReLU(z)=max(0,z), but its rule and sensitivity still require supplemental evidence.','gap',[ev('google','Exercise 2','Stacking linear calculations remains linear.')])
node('loss','How is a prediction mismatch turned into one number to reduce?','Given desired outputs y1,y2, choose L=((p1-y1)^2+(p2-y2)^2)/2. Squaring makes either error direction costly; summing combines outputs. The factor 1/2 is a declared example convention. Across training examples, average their losses.',evidence=[ev('sanderson','Quick Recap','Squared output differences are added; average example costs gives the objective.')])
node('sensitivity','What does sensitivity mean without assuming calculus?','For a very small change delta in one number, the resulting change in another is approximately sensitivity times delta. Sign indicates increase or decrease; magnitude gives the scale near the present values. A derivative is this limiting change ratio, not the historical share of blame for an existing error.',evidence=[ev('stanford','Simple expressions and interpretation of the gradient','Derivatives express effects of tiny changes, with sign and magnitude.')])
node('local_rules','How do addition, multiplication, squaring, and ReLU respond to tiny changes?','Addition passes a change with factor 1. Multiplication by a fixed number scales the change by that number. Squaring and ReLU rules need explicit justification for a reader without calculus.','gap',[ev('stanford','Simple expressions and interpretation of the gradient','Addition has local factor 1; a multiplication input has local factor equal to its other input.')])
node('chain','How does a small effect pass through successive calculations?','If an early change is multiplied by local factor a in one operation and then factor b in another, the resulting change is approximately ab times the original change. Multiply these local factors through a path: this is the chain rule.',evidence=[ev('stanford','Compound expressions, chain rule, backpropagation','Multiplying local sensitivities composes effects along sequential operations.')])
node('branch','What if one value affects the loss along multiple paths?','Add the sensitivities returning along every use of the value. The same tiny change affects each use, and the resulting effects on the total loss combine, potentially reinforcing or canceling.',evidence=[ev('stanford','Patterns in backward flow','Branch contributions are added rather than overwritten.'),ev('sanderson','The Intuition for Backpropagation','Earlier hidden values can receive competing desired changes from several outputs.')])
node('reverse','Why work backward, and what must be saved?','Save intermediate values while predicting. Set loss sensitivity to itself to 1. Visit operations from the loss backward: multiply each incoming sensitivity by the operation’s local factor and add contributions at shared values. This reuses each downstream result instead of tracing every parameter-to-loss path separately.',evidence=[ev('stanford','Backprop in practice: Staged computation','Forward intermediate values support local backward computations.'),ev('pytorch','More on Computational Graphs','Backward derivative functions apply the chain rule and accumulate results to parameters.')])
node('gradient','What information does the completed backward pass provide?','The parameter gradient is the collection of sensitivities of the chosen scalar loss to each weight and bias, holding other parameters fixed at current values. It describes local change, not a unique decomposition of the existing loss.',evidence=[ev('stanford','Simple expressions and interpretation of the gradient','Gradient collects sensitivities to multiple quantities.')])
node('update','How are these sensitivities used to learn?','For each parameter theta, choose a small positive step size eta and set theta_new=theta-eta*gradient_theta. Locally, the predicted loss change is -eta times the sum of squared parameter sensitivities, so a nonzero gradient gives a decrease for a sufficiently small step where the loss is differentiable. Repeat new forward and backward passes. Backprop computes the gradient; the update is a separate optimization choice.',evidence=[ev('sanderson','What is Backpropagation?; stochastic gradient descent discussion','Opposite-gradient adjustments reduce cost locally.'),ev('pytorch','Computing Gradients','Gradient computation supplies information for optimization, not an update policy.')])
node('limits','Why can a gradient-based adjustment fail to lower the desired error?','Sensitivities describe the present neighborhood: a large step can behave differently. Examples can favor conflicting changes, so average their gradients for the training objective or estimate with a batch. Lower training loss does not itself establish performance on unseen data. At activation corners ordinary derivative reasoning needs an explicit convention.','gap',[ev('stanford','Simple expressions and interpretation of the gradient','Sensitivities describe local behavior.'),ev('sanderson','discussion of competing desired changes and stochastic gradient descent','Examples can favor conflicting changes; batches combine their contributions.')])
node('trace_forward','What exact tiny network and prediction error will we use?','Constructed example: x=2, w=1, b=0, h=ReLU(w*x+b)=2; p1=v1*h with v1=1 gives 2; p2=v2*h with v2=0.5 gives 1. Desired outputs are y1=1,y2=2. L=((2-1)^2+(1-2)^2)/2=1. Four adjustable parameters are w,b,v1,v2; output biases are omitted deliberately.','gap')
node('trace_backward','What numerical sensitivity does each parameter receive?','Planned trace at the example values: dL/dp1=1, dL/dp2=-1; dL/dv1=2, dL/dv2=-2. The shared h receives 1*1+(-1)*0.5=0.5. ReLU is active, so dL/dw=0.5*2=1 and dL/db=0.5. Verify against independent small perturbations.','gap')
node('trace_update','Does a small simultaneous update actually reduce this example loss?','With eta=0.1, update w to 0.9, b to -0.05, v1 to 0.8, v2 to 0.7. Recompute all operations to check the new loss; predicted local reduction and actual reduction should be distinguished.','gap')
node('target','How does a tiny network work out each weight’s influence on prediction error and use that information to learn?','Backpropagation computes how an infinitesimal change in each parameter would change a scalar loss. It combines local arithmetic sensitivities backward through all paths. A separate update moves parameters opposite those sensitivities; repeat to learn from examples. Complete the trace and qualify the local meaning before finalizing.','gap')
edges=[]
def edge(a,b,w):edges.append({'from':a,'to':b,'why':w})
for a,b,w in [
('arithmetic','parameters','Weighted sums require multiplication and addition.'),('parameters','activation','An activation acts on the weighted sum whose role must be understood.'),('parameters','loss','Loss compares network outputs to desired outputs.'),('arithmetic','sensitivity','A ratio of changes and signed scaling use known arithmetic.'),('sensitivity','local_rules','Local rules quantify the tiny-change effect just defined.'),('activation','local_rules','The ReLU sensitivity requires its piecewise forward rule.'),('local_rules','chain','Path sensitivity composes the local arithmetic factors.'),('sensitivity','branch','Combining contributions requires understanding what each sensitivity measures.'),('chain','reverse','Backward multiplication is the chain rule applied locally.'),('branch','reverse','The backward algorithm must accumulate every use of shared values.'),('parameters','reverse','Saved intermediate values come from evaluating the network.'),('loss','reverse','The scalar loss is the backward starting point.'),('reverse','gradient','Collecting the backward results at parameters yields the gradient.'),('gradient','update','Parameter updates need the corresponding signed sensitivities.'),('update','limits','Step-size limitations and repeated training qualify the learning rule.'),('activation','trace_forward','The trace needs the exact hidden activation calculation.'),('loss','trace_forward','The trace needs an explicit scalar error formula.'),('trace_forward','trace_backward','Local backward factors depend on the numerical forward values.'),('reverse','trace_backward','The numerical trace needs the backward multiplication and accumulation procedure.'),('trace_backward','trace_update','Parameter changes need the computed parameter sensitivities.'),('update','trace_update','The numerical changes instantiate the chosen update rule.'),('trace_update','target','The full numerical example makes the learning mechanism traceable.'),('limits','target','The answer must distinguish local sensitivity and training progress from stronger guarantees.')]:edge(a,b,w)
graph={'topic':'Backpropagation','target':'target','reader_assumptions':['Comfortable with arithmetic and basic Python variables and functions.','No calculus knowledge assumed.','Can interpret a numerical function as a sequence of arithmetic operations.'], 'scope':{'included':['Scalar loss, forward evaluation, local sensitivities, chain rule, shared paths, reverse computation, gradient update, traceable tiny example'],'excluded':['Full explanation report','Matrix notation and convergence proofs','Optimizer survey','Implementation tutorial']},'nodes':nodes,'edges':edges,'revisions':[]}
initial=json.loads(json.dumps(graph))
graph['revisions'].append({'round':0,'stage':'initial before supplemental research','initial_graph':initial,'gaps':['Justify squared loss local factor and ReLU derivative with no calculus baseline.','Check activation corner convention and the limits of gradient updates.','Independently verify forward/backward/update arithmetic.'],'searches':[],'evidence':[],'changes':[]})
(root/'dag.initial.json').write_text(json.dumps(graph,indent=2)+'\n')
(root/'dag.json').write_text(json.dumps(graph,indent=2)+'\n')
